const resourceGuides = {
  'metal-roofing-perth': {
    scope: 'Metal roofing is best read as a connected assembly: sheets, laps, fasteners, flashings, roof edges and drainage components all meet along the same water path. This guide is for putting a visible observation into useful words before an enquiry. It cannot determine the condition of a roof from a description, photograph or view from the ground.',
    observe: ['Start with the broad location: front, rear, side, ridge, valley, eave or a point near a wall.', 'Note whether the visible change is on a sheet, at a lap, around a fixing, beside a flashing or at the roof edge.', 'Compare the area with an adjacent section from a safe ground-level position. A difference in alignment, colour, surface finish or water marking is useful context.', 'If the observation follows rain or wind, record the date, approximate duration and whether water was seen inside, at an eave or near a downpipe.'],
    context: 'Perth weather can make different details easier to notice at different times. Dry conditions can make surface texture and sheet lines easier to compare. Rain can make water paths more visible at edges, valleys, gutters and outlets. Neither observation, by itself, identifies a cause. It is more useful to record the relationship between the visible point and its neighbouring parts than to name a repair in advance.',
    record: 'For an enquiry, include the property suburb, roof type if known, the room or exterior elevation involved, and whether the observation is new, repeated or changing. Ground-level photos can help show the general setting when they are taken without accessing the roof. If you have previous photos, identify when they were taken rather than assuming that every visual difference is recent.',
    stop: 'Do not climb onto a metal roof, walk on roof sheets, lean ladders against uncertain edges or approach roof areas near electrical services simply to investigate. If there is fallen material, active water near electrical equipment, a damaged overhead service or another immediate hazard, keep clear and use the relevant emergency or qualified service pathway. For non-urgent questions, share the visible detail and let the next conversation establish the appropriate scope.',
    related: '<a href="/metal-roof-repairs/">Read metal roof repair context</a> · <a href="/flashing-repairs/">Read about flashing junctions</a> · <a href="/contact/">Make an enquiry</a>'
  },
  'gutter-warning-signs': {
    scope: 'A gutter observation is usually more useful when it includes the roof edge, the outlet and the downpipe rather than the gutter alone. This guide helps residents and property managers describe visible drainage behaviour in a way that can support a clearer enquiry. It does not confirm whether a gutter needs cleaning, adjustment, repair or replacement.',
    observe: ['Identify the gutter run and the nearest downpipe or outlet. A front elevation, rear patio line or side boundary is often enough to orient the description.', 'Look from a safe position for water marks below the gutter, a visible low point, separated-looking joins, rust staining, debris at an outlet or water landing where it is not expected.', 'During or after rain, note whether water appears to pass over an edge, from a join, from an outlet or at the base of a downpipe.', 'Separate the observation from the conclusion. “Water was visible at the corner outlet after steady rain” is more helpful than assuming why it happened.'],
    context: 'Water reaches a gutter from the roof surface, then moves toward an outlet and downpipe. Leaves, nearby trees, roof material, gutter fall, joins and the condition of the connected downpipe can all be relevant to what is visible. A single overflowing point may not describe the whole drainage route, and a dry-day view may not show how the line behaves in rain. Notes made at more than one time can be useful.',
    record: 'For a practical enquiry, write down the property suburb, the affected side of the building, whether the event occurred during light, steady or heavy rain, and whether water reached walls, eaves or ground areas. Ground-level photos of the outlet, downpipe and surrounding path can provide context. If the concern is recurring, include how often it has been noticed and whether nearby trees or recent weather are part of the picture.',
    stop: 'Do not work from a roof, unstable ladder, wet surface or elevated gutter line to collect information. Keep away from overflow near electrical equipment and do not attempt to clear a roof-level blockage during a storm. If water is creating an immediate electrical or structural safety concern, treat it as a safety matter first. Otherwise, a short written record and safe photographs are enough to begin a discussion.',
    related: '<a href="/gutter-repairs/">Read gutter repair context</a> · <a href="/gutters-downpipes/">Explore gutters and downpipes</a> · <a href="/contact/">Make an enquiry</a>'
  },
  'roof-leak-inspection': {
    scope: 'A roof-leak enquiry usually begins with where water appears, when it appears and what has changed around that time. Water can travel away from the point where it entered, so an interior mark is a starting point for careful description rather than proof of one particular roof detail. This guide is intended to organise observations before a property-specific discussion.',
    observe: ['Record the room, ceiling area, wall area, opening or external elevation where water, staining, dampness or a drip is visible.', 'Note the weather context: wind-driven rain, steady rain, a brief shower, a storm event or a time when no rain was noticed.', 'Look for nearby but separate features that may help describe location, such as a skylight, chimney, valley, roof edge, wall junction, bathroom exhaust or upper-storey window.', 'If a mark changes, photograph it from the same position and record the date. This avoids relying only on memory when comparing later observations.'],
    context: 'A visible indoor mark and an external roof feature can be related, but they are not automatically the same point in the building. Roof coverings, flashings, penetrations, wall junctions, condensation sources and drainage lines are different parts of a broader building envelope. The useful task for an enquiry is to map what can be seen and when it occurs, not to make a diagnosis from one symptom.',
    record: 'Share the property suburb, the affected room or elevation, the timing of the observation and any relevant weather pattern. Tell us if the issue is a first occurrence, a repeat event or a change after a specific storm. Photos of the room and safe ground-level exterior views can be useful when clearly labelled by location. If you have already taken steps to contain water safely inside, note that as part of the history.',
    stop: 'Avoid roof access, wet ceilings, electrical fittings and areas where water may be close to power. Do not remove building elements or enter an unsafe roof space simply to locate a source. If water is near electrical equipment, there is ceiling collapse risk, or severe weather is creating an immediate danger, seek the appropriate urgent assistance. For routine enquiries, document what is visible and use direct contact details to discuss it.',
    related: '<a href="/roof-leak-repairs/">Read roof leak repair context</a> · <a href="/roof-inspection/">Read roof inspection context</a> · <a href="/contact/">Make an enquiry</a>'
  },
  'roof-maintenance-basics': {
    scope: 'Roof maintenance starts with consistent, safe observations rather than assumptions about a repair. A short record of changes at roof surfaces, ridges, flashings, gutters and downpipes can be more useful than a one-off glance. This guide describes what can be noted from normal accessible areas; it is not a roof-access instruction or a maintenance schedule for every building.',
    observe: ['Choose a safe ground-level or readily accessible viewing point and use the same point when comparing the roofline over time.', 'Notice changed lines, accumulated debris at visible drainage points, staining around eaves, altered surface appearance or a new-looking gap at a junction.', 'After rain, observe where water leaves the roof edge and whether it appears to travel through the gutter and downpipe route as expected.', 'Keep the season and nearby environment in mind. Trees, leaf fall, wind exposure, roof material and the age of an observation can all affect what is seen.'],
    context: 'Routine upkeep decisions depend on the material, roof design, accessibility, local surroundings and the condition that is actually present. The same visible mark may have different context on separate properties. It is therefore more useful to describe location, timing and the relationship between components than to rely on generic rules. Maintenance information should help prepare questions, not substitute for an assessment of a particular roof.',
    record: 'A simple maintenance note can include the date, weather, viewing point, roof or drainage section, what changed and whether the observation was confirmed in more than one condition. Add photos only when they can be taken safely. This creates a clearer chronology for homeowners, tenants, property managers or anyone coordinating a discussion about the property.',
    stop: 'Do not treat routine maintenance as a reason to access a roof, work near an edge, use a ladder on unstable ground or approach overhead electrical services without the appropriate controls. Storm conditions, wet surfaces and damaged materials are not suitable times for close inspection. If there is a safety concern, stay clear. If the matter is not urgent, collect the safe observations you have and discuss the next step directly.',
    related: '<a href="/roof-maintenance/">Read roof maintenance context</a> · <a href="/roof-repairs/">Explore roof repair information</a> · <a href="/contact/">Make an enquiry</a>'
  },
  'roof-flashing-explained': {
    scope: 'Flashing is a term used for weatherproofing details where roof materials meet another surface or change direction. It may be seen near walls, chimneys, skylights, penetrations, valleys or transitions between materials. This guide explains how to describe a flashing-related observation clearly; it does not determine whether a visible line or mark needs a specific repair.',
    observe: ['State the feature beside the observation: wall, chimney, skylight, pipe penetration, valley, roof-to-wall line or another visible junction.', 'Note whether the change looks like lifting, separation, staining, corrosion, a gap, a changed overlap or water appearing nearby after weather.', 'Describe the roof material adjoining the junction if known, such as tile or metal, and whether the detail is close to a ridge, eave or drainage line.', 'Use a ground-level photo only where it can safely show the wider relationship between the roof area and the adjoining feature.'],
    context: 'A junction manages a transition between materials and directions, so the surrounding roof surface and drainage route matter. A stain near a wall does not by itself identify the path of water, and a visible edge does not reveal every concealed layer. The strongest enquiry notes keep the feature, material, nearby roof section and weather timing together. This gives a clearer starting point than trying to name the construction method from a distance.',
    record: 'For an enquiry, include the property suburb, whether the observation is inside or outside, which feature it is next to, and whether wind or rain changes what is visible. If water has appeared indoors, use the same language as the roof-leak guide: identify the room, mark or drip location and weather conditions. Link the interior and exterior notes only when you know they refer to the same part of the building.',
    stop: 'Do not access a high junction, roof penetration, skylight, chimney or wall edge to inspect it. These areas can involve fall risks, fragile materials and nearby electrical services. Avoid probing, lifting or removing materials to test a theory. Where there is an urgent safety issue, keep clear and seek appropriate assistance. For a non-urgent observation, a safe description is enough to start a focused conversation.',
    related: '<a href="/flashing-repairs/">Read flashing repair context</a> · <a href="/roof-leak-repairs/">Read roof leak context</a> · <a href="/contact/">Make an enquiry</a>'
  },
  'drainage-after-rain': {
    scope: 'Rain can make the route from roof surface to gutter, outlet, downpipe and ground connection easier to observe. This guide helps turn that short window into useful notes without asking anyone to work in unsafe conditions. It is not a drainage diagnosis and does not prescribe cleaning, adjustment or repair work for a particular property.',
    observe: ['From a safe covered or ground-level position, identify where water appears to leave the roof edge and enter the gutter line.', 'Watch for water at a gutter corner, outlet, downpipe join, eave, wall or ground connection, and note whether it travels, pools, overflows or lands in an unexpected place.', 'Record the rainfall pattern as best you can: brief shower, steady rain, strong wind with rain or a severe-weather event.', 'After the rain has passed and conditions are safe, compare what you observed with visible water marks, debris, staining or ground drainage paths.'],
    context: 'Drainage is a route rather than a single component. A visible change at a gutter may relate to water arriving from the roof surface, passing an outlet or continuing through a downpipe. Ground levels, leaf litter, tree cover and the placement of connected components can also shape what is noticed. The most useful account distinguishes what was actually seen from what is only suspected.',
    record: 'A concise record can include the date, rainfall conditions, the side of the property, the gutter or downpipe location, whether water reached the building or ground, and whether the observation has happened before. Photographs or short videos taken from a safe position can help show timing and location. Do not delay an urgent safety response to collect documentation.',
    stop: 'Do not climb ladders, access roofs, clear gutters or handle electrical equipment during rain or severe weather. Stay clear of fallen branches, damaged roof materials, overhead electrical infrastructure and water near power. The Bureau of Meteorology publishes current official warnings; use those warnings and local emergency instructions as the priority during severe conditions. When it is safe, use the observation record to make a non-urgent enquiry.',
    related: '<a href="/gutters-downpipes/">Explore gutters and downpipes</a> · <a href="/downpipe-repairs/">Read downpipe repair context</a> · <a href="/contact/">Make an enquiry</a>'
  }
};

const resourceGuideAppendix = (guide) => `<section class="section resource-guide-detail"><div class="narrow"><p class="eyebrow">PRACTICAL READING / PERTH</p><h2>Use the detail without jumping to a conclusion.</h2><p>${guide.scope}</p><h2>What you can safely observe</h2><ul>${guide.observe.map((item) => `<li>${item}</li>`).join('')}</ul><h2>Keep the wider context in view</h2><p>${guide.context}</p><h2>How to prepare a useful enquiry</h2><p>${guide.record}</p><h2>When to stop and seek help</h2><p>${guide.stop}</p><h2>Related Ellis Services Group pages</h2><p>${guide.related}</p><h2>Sources and further reading</h2><p>For general working-at-heights safety information, see <a href="https://www.safeworkaustralia.gov.au/safety-topic/hazards/working-heights" target="_blank" rel="noopener noreferrer">Safe Work Australia: working at heights</a>. For current Western Australian weather warnings, see <a href="https://www.bom.gov.au/wa/warnings/" target="_blank" rel="noopener noreferrer">Bureau of Meteorology WA warnings</a>. These external resources are provided for general safety and weather awareness; they do not replace property-specific assessment.</p><p><strong>Editorial note:</strong> This guide is general information prepared by Ellis Services Group. It is designed to help visitors describe visible roof and drainage details clearly, not to diagnose a property or direct roof-access work.</p></div></section>`;

